const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

let idx = 0;
const N = parseInt(data[idx++], 10);
const D = parseFloat(data[idx++]);

const P = new Array(N);
const C = new Array(N);

for (let i = 0; i < N; i++) {
    P[i] = parseFloat(data[idx++]);
    C[i] = parseFloat(data[idx++]);
}

const dp = new Array(N).fill(Infinity);
dp[0] = 0;

for (let j = 1; j < N; j++) {
    for (let i = 0; i < j; i++) {
        const dist = P[j] - P[i];
        const time = dp[i] + (dist * dist) / C[i];
        if (time < dp[j]) dp[j] = time;
    }
}

let ans = Infinity;
for (let i = 0; i < N; i++) {
    const dist = D - P[i];
    const time = dp[i] + (dist * dist) / C[i];
    if (time < ans) ans = time;
}

console.log(ans.toFixed(3));
